function addAcademy(){const sec=document.getElementById("academia");if(!sec||sec.dataset.v10academy)return;sec.dataset.v10academy="1";const wrap=document.createElement("div");wrap.className="academyV10";wrap.innerHTML='<div class="academyHead"><h2>Academia Yeppo B2B</h2><p>Contenido práctico para que el cliente venda mejor, compre mejor y aumente su recompra.</p></div><div class="academyGrid">'+modules.map((m,i)=>`<article><small>Módulo ${i+1} · ${m[0]}</small><h3>${m[1]}</h3><b>${m[2]}</b><p>${m[3]}</p><span>Video corto · resumen · ejercicio · mini quiz · acción comercial</span></article>`).join("")+'</div>';sec.prepend(wrap)}
function addTodayAlert(refresh=false){const a=alerts(),urgent=a.filter(x=>x.waiting);if(refresh)document.getElementById("incomingToday")?.remove();if(!a.length)return;const host=document.querySelector("#hoy .sales-hero")||document.getElementById("hoy");if(!host||document.getElementById("incomingToday"))return;const d=document.createElement("div");d.id="incomingToday";d.className="incomingToday";d.innerHTML=`<small>Radar próximos ingresos</small><b>${urgent.length?urgent.length+" alertas PRIORITARIAS · ":""}${a.length} oportunidades por SKU en camino</b><span>${new Set(a.map(x=>x.id)).size} clientes relacionados</span>`;d.onclick=()=>document.querySelector('[data-tab="incoming"]')?.click();host.appendChild(d)}

async function accessHash(v){const buf=await crypto.subtle.digest("SHA-256",new TextEncoder().encode("YEPPO-V10|"+String(v)));return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function setLocalAccess(code){localStorage.setItem(ACCESS_KEY,await accessHash(code))}
async function verifyLocalAccess(code){const h=localStorage.getItem(ACCESS_KEY);return !h||h===await accessHash(code)}
function addInteractiveManual(){if(document.getElementById("crmManual"))return;const main=document.querySelector("main");if(!main)return;const steps=[{title:"Inicio y prioridades",eyebrow:"1 · Panorama diario",image:"assets/manual/inicio.jpg",body:"Empieza aquí para entender qué necesita atención hoy. Los indicadores resumen ventas, clientes activos, oportunidades y tareas pendientes.",points:["Revisa primero las tareas que vencen hoy.","Usa Próximas acciones para atender cuentas P1 y P2.","Los accesos rápidos te llevan a los módulos principales."],target:"home",action:"Ir al Inicio"},{title:"Pipeline comercial",eyebrow:"2 · Oportunidades",image:"assets/manual/pipeline.jpg",body:"El pipeline muestra en qué etapa está cada oportunidad: prospecto, contacto, propuesta y ganada. Cada tarjeta representa una cuenta y su siguiente paso.",points:["Mueve una cuenta cuando exista un avance real.","Abre la tarjeta para revisar la Ficha 360 antes de contactar.","Mantén una próxima acción y una fecha en cada oportunidad."],tab:"pipeline",action:"Abrir Pipeline"},{title:"Cartera de clientes",eyebrow:"3 · Clientes",image:"assets/manual/clientes.jpg",body:"Consulta la cartera completa, filtra por prioridad, segmento o KAM y abre la ficha de una cuenta sin perder el contexto comercial.",points:["Busca por nombre, email o empresa.","Prioridad P1 requiere atención antes que P2 o P3.","Usa la Ficha 360 para editar o registrar una gestión."],target:"clients",action:"Abrir Clientes"},{title:"Tareas y responsables",eyebrow:"4 · Organización",image:"assets/manual/tareas.jpg",body:"Las tareas convierten cada acuerdo en una acción concreta. Nada se guarda hasta que revisas el formulario y pulsas Guardar.",points:["Escribe una acción específica y fácil de comprobar.","Define tipo, cliente, responsable y fecha.","Marca la tarea como terminada solo después de realizarla."],tab:"tareas",action:"Abrir Tareas"},{title:"Ficha 360 y contacto",eyebrow:"5 · Gestión de cuenta",image:"assets/manual/ficha-360.jpg",body:"La Ficha 360 reúne información, ventas, oportunidades, actividad y contacto. Desde aquí puedes preparar un guion, editarlo y abrir WhatsApp o Gmail.",points:["Agrega contexto antes de generar el mensaje.","Revisa y edita siempre el guion antes de enviarlo.","Crea una tarea para asegurar el próximo seguimiento."],target:"clients",action:"Buscar un cliente"},{title:"Usuarios, KAM y auditoría",eyebrow:"6 · Configuración",image:"assets/manual/configuracion.jpg",body:"En Configuración puedes administrar usuarios, roles y responsables. El historial permite saber quién creó tareas, editó clientes o movió oportunidades.",points:["Administrador: controla usuarios y toda la operación.","KAM: gestiona su cartera, tareas y oportunidades.","Solo lectura: consulta información sin modificarla."],target:"settings",action:"Abrir Configuración"}];let index=0;const key="yeppoCRMManualSeen",readSeen=()=>{try{return JSON.parse(localStorage.getItem(key)||"[]")}catch(e){return[]}},writeSeen=seen=>localStorage.setItem(key,JSON.stringify(seen));const sec=document.createElement("section");sec.id="crmManual";sec.className="panel crmManual";sec.innerHTML=`<header class="crmManualHero"><div><span>AYUDA Y RECORRIDO</span><h1>Manual interactivo del CRM B2B</h1><p>Aprende las funciones principales con capturas de la app y entra directamente a cada módulo.</p></div><button class="crmManualStart"><i class="fa-solid fa-play" aria-hidden="true"></i> Empezar recorrido</button></header><div class="crmManualProgress"><span></span><small></small></div><div class="crmManualLayout"><aside class="crmManualSteps" aria-label="Capítulos del manual"></aside><article class="crmManualStage"><div class="crmManualMedia"><img alt="" loading="eager"><span>Captura del CRM · datos de ejemplo</span></div><div class="crmManualCopy"><span class="crmManualEyebrow"></span><h2></h2><p></p><ul></ul><div class="crmManualActions"><button class="crmManualPrev"><i class="fa-solid fa-chevron-left" aria-hidden="true"></i> Anterior</button><button class="crmManualVisit"></button><button class="crmManualSeen"><i class="fa-regular fa-circle-check" aria-hidden="true"></i> Marcar como visto</button><button class="crmManualNext">Siguiente <i class="fa-solid fa-chevron-right" aria-hidden="true"></i></button></div></div></article></div>`;main.appendChild(sec);const stepHost=sec.querySelector(".crmManualSteps"),img=sec.querySelector("img"),eyebrow=sec.querySelector(".crmManualEyebrow"),title=sec.querySelector("h2"),copy=sec.querySelector(".crmManualCopy>p"),list=sec.querySelector("ul"),prev=sec.querySelector(".crmManualPrev"),next=sec.querySelector(".crmManualNext"),visit=sec.querySelector(".crmManualVisit"),seenBtn=sec.querySelector(".crmManualSeen"),bar=sec.querySelector(".crmManualProgress span"),status=sec.querySelector(".crmManualProgress small");const render=()=>{const item=steps[index],seen=readSeen();stepHost.innerHTML=steps.map((x,i)=>`<button data-manual-step="${i}" class="${i===index?"active":""} ${seen.includes(i)?"seen":""}"><i class="fa-solid ${seen.includes(i)?"fa-circle-check":"fa-circle"}" aria-hidden="true"></i><span><small>${esc(x.eyebrow)}</small><b>${esc(x.title)}</b></span></button>`).join("");stepHost.querySelectorAll("[data-manual-step]").forEach(button=>button.onclick=()=>{index=Number(button.dataset.manualStep);render()});img.src=item.image;img.alt=`${item.title} en el CRM Yeppo B2B`;eyebrow.textContent=item.eyebrow;title.textContent=item.title;copy.textContent=item.body;list.innerHTML=item.points.map(point=>`<li>${esc(point)}</li>`).join("");visit.textContent=item.action;prev.disabled=index===0;next.disabled=index===steps.length-1;seenBtn.classList.toggle("done",seen.includes(index));seenBtn.innerHTML=seen.includes(index)?'<i class="fa-solid fa-circle-check" aria-hidden="true"></i> Visto':'<i class="fa-regular fa-circle-check" aria-hidden="true"></i> Marcar como visto';bar.style.width=`${Math.round(seen.length/steps.length*100)}%`;status.textContent=`${seen.length} de ${steps.length} capítulos vistos`};const open=(step=0)=>{index=Math.max(0,Math.min(steps.length-1,Number(step)||0));document.querySelectorAll(".panel").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".tabs .tab").forEach(x=>x.classList.remove("active"));sec.classList.add("active");crmSetActiveV2("manual");window.scrollTo({top:0,behavior:"smooth"});render()};window.crmOpenManual=open;prev.onclick=()=>{if(index>0){index--;render()}};next.onclick=()=>{if(index<steps.length-1){index++;render()}};seenBtn.onclick=()=>{const seen=readSeen(),pos=seen.indexOf(index);if(pos>=0)seen.splice(pos,1);else seen.push(index);writeSeen(seen);render()};visit.onclick=()=>{const item=steps[index];if(item.target)crmActivateV2(item.target);else if(item.tab){const tab=[...document.querySelectorAll(".tabs .tab")].find(x=>x.dataset.tab===item.tab);if(tab){tab.click();crmSetActiveV2("")}}};sec.querySelector(".crmManualStart").onclick=()=>{index=0;render();sec.querySelector(".crmManualStage").scrollIntoView({behavior:"smooth",block:"start"})};document.querySelector(".crmManualNavBtnV2")?.addEventListener("click",()=>open(index));const help=document.createElement("button");help.className="crmManualHelp";help.type="button";help.setAttribute("aria-label","Abrir manual interactivo");help.title="Ayuda y manual";help.innerHTML='<i class="fa-solid fa-question" aria-hidden="true"></i>';help.onclick=()=>open(index);document.body.appendChild(help);const placeHelp=()=>{const notice=document.getElementById("shopifyLiveStatus"),noticeBottom=notice?Number.parseFloat(getComputedStyle(notice).bottom)||0:0,gap=window.innerWidth<=760?18:14;help.style.bottom=`${notice?Math.ceil(notice.getBoundingClientRect().height+noticeBottom+gap):22}px`};setTimeout(()=>{placeHelp();const notice=document.getElementById("shopifyLiveStatus");if(notice&&window.ResizeObserver)new ResizeObserver(placeHelp).observe(notice)},0);window.addEventListener("resize",placeHelp,{passive:true});render()}
function addManualBeginnerGuide(){const sec=document.getElementById("crmManual");if(!sec||sec.dataset.beginnerGuide)return;sec.dataset.beginnerGuide="1";const guides=[{goal:"Aprender a decidir qué hacer apenas comienza la jornada.",steps:["Confirma que estás usando el usuario correcto y revisa la fecha del panel.","Lee Ventas, Clientes activos, Oportunidades y Tareas como señales generales; no son una lista de trabajo.","Revisa Próximas acciones y comienza por las cuentas P1 que vencen hoy.","Entra en Mi Día para ejecutar, registrar el resultado y dejar el siguiente paso."],terms:[["P1","Atención urgente o de mayor impacto."],["P2","Importante, pero puede programarse."],["P3","Oportunidad de seguimiento sin urgencia."]],warning:"No intentes contactar a todos. Empieza por lo vencido y por las cuentas P1."},{goal:"Entender dónde está cada oportunidad y qué debe ocurrir después.",steps:["Prospecto: existe una cuenta potencial, pero todavía no hubo conversación comercial.","Contacto inicial: ya hubo contacto real y debes registrar qué respondió el cliente.","Propuesta enviada: registra fecha, monto y día de seguimiento de la propuesta.","Ganada: úsala cuando exista confirmación real; si no avanzó, deja el motivo y una nueva acción."],terms:[["Lead","Posible cliente todavía no calificado."],["Oportunidad","Cuenta con necesidad o intención comercial identificada."],["Etapa","Momento actual de la conversación comercial."]],warning:"No muevas una tarjeta por intuición. Hazlo cuando exista una acción o respuesta comprobable."},{goal:"Encontrar una cuenta y comprender rápidamente su situación.",steps:["Busca por nombre, empresa o correo; luego aplica filtros de KAM, segmento o prioridad.","Revisa segmento, última compra, venta de 90 días y próxima acción antes de abrir la cuenta.","Abre la Ficha 360 para ver ciclo de compra, tareas, actividad y oportunidades.","En Productos esperados registra los SKU que el cliente pidió; el CRM los cruzará con Próximos ingresos y Dormidos.","Si detectas un dato incorrecto, corrígelo antes de contactar al cliente."],terms:[["Segmento","Tipo de relación comercial: nueva, Growth, VIP o riesgo."],["Ciclo","Cantidad estimada de días entre compras."],["Prioridad","Orden recomendado de atención según riesgo y oportunidad."],["Dormido","Cliente que superó su ciclo habitual de recompra en 25%; si no existe ciclo, se usa un umbral de 120 días."]],warning:"No uses solamente la venta histórica: revisa también la fecha de última compra y el ciclo."},{goal:"Convertir cada acuerdo en una acción clara, asignada y con fecha.",steps:["Pulsa Crear tarea y escribe una acción específica: verbo, motivo y resultado esperado.","Selecciona el tipo de tarea, el cliente y la persona responsable.","Define una fecha realista y revisa todos los datos antes de pulsar Guardar.","Márcala como terminada únicamente después de realizarla y registrar el resultado."],terms:[["Responsable","Persona que debe ejecutar la tarea."],["Vencimiento","Fecha límite acordada para realizarla."],["Tipo","Canal o naturaleza: llamada, WhatsApp, email, propuesta o seguimiento."]],warning:"“Contactar cliente” es demasiado general. Escribe, por ejemplo: “Llamar para revisar rotación y definir reposición”."},{goal:"Preparar un contacto personalizado y dejar trazabilidad de lo conversado.",steps:["Revisa ventas, última compra, ciclo, notas y actividad reciente de la cuenta.","Agrega contexto real a la IA: qué comentó el cliente, qué necesita y cuál es el objetivo.","Genera el guion, léelo completo y edítalo para que suene natural antes de abrir WhatsApp o Gmail.","Después del contacto registra el resultado y crea la próxima tarea con responsable y fecha."],terms:[["Ficha 360","Vista completa de datos, ventas, actividad y oportunidades."],["Opportunity score","Indicador orientativo del potencial comercial."],["Interacción","Registro de un contacto y su resultado."]],warning:"WhatsApp y Gmail abren un borrador. El KAM debe revisar el mensaje antes de enviarlo."},{goal:"Administrar accesos, costos, responsables, historial y estado de la base.",steps:["Crea usuarios y asigna el rol mínimo necesario: Administrador, Supervisor, KAM o Solo lectura.","Carga costos por Excel o edita un SKU manualmente; ingrésalos siempre con IVA.","Asigna cada cliente a un KAM y entra en Reportes para filtrar la actividad del equipo por usuario y fechas.","Consulta Base CRM activa, sincronización Shopify, cobertura de costos y opciones de actualización."],terms:[["KAM","Responsable de gestionar y desarrollar una cartera de clientes."],["Auditoría","Historial de acciones con usuario, fecha y cambio registrado."],["Base CRM","Datos acumulados de clientes, pedidos, productos, costos y actividad B2B."]],warning:"No mezcles costos netos y costos con IVA. En esta pantalla todos se ingresan con IVA incluido."}];const first=document.createElement("details");first.className="crmManualFirstTime";first.open=true;first.innerHTML='<summary><i class="fa-solid fa-route" aria-hidden="true"></i><span><b>¿Es tu primera vez en el CRM?</b><small>Sigue esta ruta inicial de 15 minutos</small></span><i class="fa-solid fa-chevron-down" aria-hidden="true"></i></summary><ol><li><b>1. Inicio</b><span>Identifica las prioridades del día.</span></li><li><b>2. Clientes</b><span>Busca una cuenta de prueba y abre su Ficha 360.</span></li><li><b>3. Actividad</b><span>Revisa el historial antes de contactar.</span></li><li><b>4. Tarea</b><span>Crea un seguimiento con responsable y fecha.</span></li><li><b>5. Pipeline</b><span>Actualiza la etapa solo si hubo un avance real.</span></li></ol>';sec.querySelector(".crmManualProgress")?.after(first);const guide=document.createElement("section");guide.className="crmManualBeginnerGuide";sec.querySelector(".crmManualCopy>p")?.after(guide);const update=()=>{const active=sec.querySelector("[data-manual-step].active"),index=Math.max(0,Number(active?.dataset.manualStep)||0),item=guides[index]||guides[0];guide.innerHTML=`<div class="crmManualGoal"><small>OBJETIVO DEL CAPÍTULO</small><b>${esc(item.goal)}</b></div><div class="crmManualDetailed"><div><h3>Paso a paso</h3><ol>${item.steps.map((step,i)=>`<li><i>${i+1}</i><span>${esc(step)}</span></li>`).join("")}</ol></div><aside><h3>Glosario rápido</h3>${item.terms.map(([term,definition])=>`<dl><dt>${esc(term)}</dt><dd>${esc(definition)}</dd></dl>`).join("")}</aside></div><div class="crmManualWarning"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i><span><b>Error que debes evitar</b>${esc(item.warning)}</span></div>`};sec.addEventListener("click",()=>requestAnimationFrame(update));update()}
function addSecuritySettings(){if(document.getElementById("v10Security"))return;const tabs=document.querySelector(".tabs"),main=document.querySelector("main");if(!tabs||!main)return;const btn=document.createElement("button");btn.className="tab";btn.dataset.tab="v10security";btn.textContent="Configuración";tabs.appendChild(btn);const sec=document.createElement("section");sec.id="v10security";sec.className="panel";sec.innerHTML=`<div class="securityCard"><small>SEGURIDAD LOCAL</small><h2>Clave de acceso</h2><p>Cambia la clave adicional de esta V10 en este navegador. No modifica clientes, pipeline, acciones ni cargas.</p><label>Clave actual<input type="password" class="secCurrent" autocomplete="current-password"></label><label>Nueva clave<input type="password" class="secNew" autocomplete="new-password"></label><label>Repetir nueva clave<input type="password" class="secRepeat" autocomplete="new-password"></label><div class="securityActions"><button class="primary secSave">Cambiar clave</button></div><div class="secStatus"></div><div class="securityNote"><b>Importante:</b> esta protección es local al navegador. La clave de cifrado del archivo publicado en GitHub no se cambia desde la propia página.</div></div>`;main.appendChild(sec);btn.onclick=()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".panel").forEach(x=>x.classList.remove("active"));btn.classList.add("active");sec.classList.add("active")};sec.querySelector(".secSave").onclick=async()=>{const cur=sec.querySelector(".secCurrent").value,n=sec.querySelector(".secNew").value,r=sec.querySelector(".secRepeat").value,st=sec.querySelector(".secStatus");if(!n||n.length<6){st.textContent="La nueva clave debe tener al menos 6 caracteres.";return}if(n!==r){st.textContent="Las nuevas claves no coinciden.";return}if(!(await verifyLocalAccess(cur))){st.textContent="La clave actual no es correcta.";return}await setLocalAccess(n);sec.querySelectorAll("input").forEach(i=>i.value="");st.textContent="Clave local actualizada correctamente."}}

const COST_TAX_RATE=.19;
function crmDbPut(store,row){return crmDbOpen().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).put(row);tx.oncomplete=()=>resolve(row);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)}))}
function crmDbPutMany(store,rows){return crmDbOpen().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite"),os=tx.objectStore(store);rows.forEach(row=>os.put(row));tx.oncomplete=()=>resolve(rows.length);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)}))}
async function loadProductCosts(){try{productCosts=(await crmDbAll("productCosts")).sort((a,b)=>String(b.effectiveDate||"").localeCompare(String(a.effectiveDate||"")));return productCosts}catch(e){console.error("Costos CRM:",e);productCosts=[];return productCosts}}
function normalizeCostDate(value){if(value instanceof Date&&!Number.isNaN(value.getTime()))return value.toISOString().slice(0,10);const s=String(value||"").trim();if(!s)return new Date().toISOString().slice(0,10);const latin=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})$/);if(latin){const y=latin[3].length===2?`20${latin[3]}`:latin[3];return `${y}-${latin[2].padStart(2,"0")}-${latin[1].padStart(2,"0")}`}const iso=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);return iso?`${iso[1]}-${iso[2].padStart(2,"0")}-${iso[3].padStart(2,"0")}`:new Date().toISOString().slice(0,10)}
function parseCostNumber(value){if(typeof value==="number")return Number.isFinite(value)?value:0;let s=String(value??"").trim().replace(/[$\s]/g,"").replace(/[^0-9,.-]/g,"");if(!s)return 0;if(s.includes(",")){s=s.replace(/\./g,"").replace(",",".")}else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,"");return Math.max(0,Number(s)||0)}
function costHeader(value){return norm(String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," "))}
function costAt(sku,date=new Date().toISOString().slice(0,10)){const key=norm(sku),day=String(date||"").slice(0,10)||"9999-12-31";return productCosts.filter(x=>norm(x.sku)===key&&String(x.effectiveDate||"")<=day).sort((a,b)=>String(b.effectiveDate||"").localeCompare(String(a.effectiveDate||"")))[0]||null}
function latestCosts(){const out=new Map();productCosts.slice().sort((a,b)=>String(b.effectiveDate||"").localeCompare(String(a.effectiveDate||""))).forEach(row=>{const key=norm(row.sku);if(key&&!out.has(key))out.set(key,row)});return out}
function productCostName(sku,products=[]){const key=norm(sku),row=products.find(x=>norm(x.sku)===key)||window.SHOPIFY_LIVE_PRODUCTS_BY_SKU?.[key];return row?.product||row?.title||row?.name||""}
function costMoneyValue(value){if(value==null)return 0;if(typeof value==="number")return value;if(typeof value==="object")return +(value.amount??value.shopMoney?.amount??value.presentmentMoney?.amount??0)||0;return parseCostNumber(value)}
async function saveProductCost({sku,product,costGross,effectiveDate,source="manual"}){const cleanSku=String(sku||"").trim(),gross=parseCostNumber(costGross),date=normalizeCostDate(effectiveDate);if(!cleanSku)throw new Error("Ingresa un SKU.");if(!(gross>0))throw new Error("Ingresa un costo con IVA mayor que cero.");const actor=window.CRMUsers?.profile?.()||{};const row={id:`${norm(cleanSku)}|${date}`,sku:cleanSku,product:product||"",costGross:Math.round(gross*100)/100,costNet:Math.round(gross/(1+COST_TAX_RATE)*100)/100,taxRate:19,effectiveDate:date,source,updatedAt:new Date().toISOString(),updatedBy:actor.full_name||"Matías"};await crmDbPut("productCosts",row);window.CRMUsers?.audit?.("product_cost_saved","product_cost",row.id,`Actualizó el costo de ${cleanSku} a ${moneyCLP(row.costGross)} IVA incluido`,{sku:cleanSku,costGross:row.costGross,costNet:row.costNet,effectiveDate:date,source});return row}
function downloadCostTemplate(){const csv='SKU;Producto;Costo con IVA;Vigente desde\r\nCOSRX-001;Ejemplo producto;11900;22/09/2026\r\n',blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="Plantilla_costos_B2B_con_IVA.csv";a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function readCostWorkbook(file){return new Promise((resolve,reject)=>{if(!window.XLSX){reject(new Error("El lector de Excel todavía no está disponible. Espera unos segundos e inténtalo nuevamente."));return}const reader=new FileReader();reader.onload=()=>{try{const wb=XLSX.read(reader.result,{type:"array",cellDates:true}),ws=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(ws,{defval:"",raw:true});resolve(rows)}catch(e){reject(new Error("No pude leer el archivo: "+e.message))}};reader.onerror=()=>reject(new Error("No pude abrir el archivo."));reader.readAsArrayBuffer(file)})}
function rowCostValue(row,names){const entries=Object.entries(row).map(([key,value])=>[costHeader(key),value]);for(const name of names){const found=entries.find(([key])=>(key===name||key.includes(name))&&!key.includes("neto"));if(found&&String(found[1]??"").trim()!=="")return found[1]}return""}
async function importCostWorkbook(file){const rows=await readCostWorkbook(file),products=await crmDbAll("products").catch(()=>[]),prepared=[],errors=[];rows.forEach((raw,index)=>{const sku=String(rowCostValue(raw,["sku","codigo sku","codigo producto","codigo"])||"").trim(),gross=parseCostNumber(rowCostValue(raw,["costo con iva","costo iva incluido","costo unitario con iva","costo unitario","costo"])),date=normalizeCostDate(rowCostValue(raw,["vigente desde","fecha vigencia","fecha"])),product=String(rowCostValue(raw,["producto","nombre producto","nombre"])||productCostName(sku,products)||"").trim();if(!sku||!(gross>0)){if(Object.values(raw).some(v=>String(v).trim()))errors.push(index+2);return}const actor=window.CRMUsers?.profile?.()||{};prepared.push({id:`${norm(sku)}|${date}`,sku,product,costGross:Math.round(gross*100)/100,costNet:Math.round(gross/(1+COST_TAX_RATE)*100)/100,taxRate:19,effectiveDate:date,source:"excel",updatedAt:new Date().toISOString(),updatedBy:actor.full_name||"Matías"})});if(!prepared.length)throw new Error("No encontré filas válidas. La planilla necesita las columnas SKU y Costo con IVA.");const unique=[...new Map(prepared.map(row=>[row.id,row])).values()];await crmDbPutMany("productCosts",unique);window.CRMUsers?.audit?.("product_costs_imported","product_cost","excel",`Importó ${unique.length} costos de productos desde Excel`,{file:file.name,loaded:unique.length,ignored:errors.length});return{loaded:unique.length,ignored:errors.length}}
function extractOrderProfitability(orders){let salesNet=0,costNet=0,matchedLines=0,totalLines=0,ordersWithLines=0;const missing=new Set();for(const order of orders){const lines=order.lineItems||order.line_items||order.items||order.products||order.orderLines||[];if(!Array.isArray(lines)||!lines.length)continue;ordersWithLines++;const date=String(order.date||order.createdAt||order.created_at||order.processedAt||new Date().toISOString()).slice(0,10);for(const line of lines){const sku=String(line.sku||line.variantSku||line.variant?.sku||"").trim(),qty=Math.max(1,+(line.quantity??line.qty??line.units??1)||1);if(!sku)continue;totalLines++;const cost=costAt(sku,date);if(!cost){missing.add(sku);continue}let gross=costMoneyValue(line.discountedTotalSet||line.discounted_total_set||line.totalSet||line.total||line.subtotal);if(!(gross>0)){const unit=costMoneyValue(line.discountedUnitPriceSet||line.discountedUnitPrice||line.priceSet||line.price||line.unitPrice);gross=unit*qty}if(!(gross>0))continue;salesNet+=gross/(1+COST_TAX_RATE);costNet+=cost.costNet*qty;matchedLines++}}const profit=salesNet-costNet,margin=salesNet>0?profit/salesNet*100:0;return{salesNet,costNet,profit,margin,matchedLines,totalLines,ordersWithLines,missing:[...missing]}}
async function catalogProfitability(){const products=await crmDbAll("products").catch(()=>[]),latest=latestCosts(),rows=[];for(const [key,cost] of latest){const product=products.find(x=>norm(x.sku)===key)||window.SHOPIFY_LIVE_PRODUCTS_BY_SKU?.[key],priceGross=+(product?.price??product?.compareAtPrice??0)||0,priceNet=priceGross/(1+COST_TAX_RATE),margin=priceNet>0?(priceNet-cost.costNet)/priceNet*100:null;rows.push({...cost,product:cost.product||product?.product||product?.title||"",priceGross,priceNet,margin})}return{products,rows,coverage:products.length?latest.size/products.length*100:0,averageMargin:(()=>{const valid=rows.filter(x=>x.margin!=null);return valid.length?valid.reduce((sum,x)=>sum+x.margin,0)/valid.length:null})()}}
async function renderProfitabilityReport(){const host=document.getElementById("crmProfitabilityReport");if(!host)return;const [orders,reference]=await Promise.all([crmDbAll("orders").catch(()=>[]),catalogProfitability()]),actual=extractOrderProfitability(orders),hasActual=actual.matchedLines>0;host.innerHTML=`<div class="crmProfitHead"><div><small>RENTABILIDAD B2B</small><h2>${hasActual?"Margen real de pedidos":"Preparación del margen"}</h2><p>${hasActual?"Venta y costo netos, ambos sin IVA, calculados con el costo vigente en la fecha del pedido.":"Los costos ya pueden cargarse. El margen real aparecerá cuando los pedidos incluyan el detalle de SKU y unidades."}</p></div><span class="crmVatBadge">Costos ingresados con IVA · conversión automática 19%</span></div><div class="crmProfitKpis">${(hasActual?[["Venta neta analizada",moneyCLP(actual.salesNet)],["Costo neto",moneyCLP(actual.costNet)],["Utilidad bruta",moneyCLP(actual.profit)],["Margen bruto",actual.margin.toFixed(1)+"%"]]:[["SKU con costo",latestCosts().size],["Cobertura catálogo",reference.coverage.toFixed(0)+"%"],["Margen catálogo promedio",reference.averageMargin==null?"Sin precios":reference.averageMargin.toFixed(1)+"%"],["Pedidos con detalle SKU",actual.ordersWithLines]]).map(([label,value])=>`<article><span>${label}</span><b>${value}</b></article>`).join("")}</div><div class="crmProfitFoot"><span>${hasActual?`${actual.matchedLines} de ${actual.totalLines} líneas calculadas`:`${reference.products.length} SKU en catálogo · ${latestCosts().size} con costo cargado`}</span>${actual.missing.length?`<b>Sin costo: ${esc(actual.missing.slice(0,8).join(", "))}${actual.missing.length>8?"…":""}</b>`:""}<button type="button" class="crmGoCosts">Gestionar costos</button></div>`;host.querySelector(".crmGoCosts").onclick=()=>crmActivateV2("settings")}
function addProfitabilityReport(){const panel=document.getElementById("dashboard");if(!panel||document.getElementById("crmProfitabilityReport"))return;const box=document.createElement("section");box.id="crmProfitabilityReport";box.className="crmProfitabilityReport";panel.prepend(box);renderProfitabilityReport()}
async function drawCostManager(host,query=""){const reference=await catalogProfitability(),latest=latestCosts(),q=norm(query),filtered=reference.rows.filter(row=>!q||norm([row.sku,row.product].join(" ")).includes(q)).sort((a,b)=>String(a.sku).localeCompare(String(b.sku))),missing=Math.max(0,reference.products.length-latest.size);host.querySelector(".crmCostKpis").innerHTML=[["SKU catálogo",reference.products.length],["Costos cargados",latest.size],["Faltan costos",missing],["Margen ref. promedio",reference.averageMargin==null?"—":reference.averageMargin.toFixed(1)+"%"]].map(([label,value])=>`<article><span>${label}</span><b>${value}</b></article>`).join("");const rows=host.querySelector(".crmCostRows");rows.innerHTML=filtered.length?filtered.slice(0,100).map(row=>`<div class="crmCostRow"><span><b>${esc(row.sku)}</b><small>${esc(row.product||"Producto sin nombre")}</small></span><span><small>Con IVA</small><b>${moneyCLP(row.costGross)}</b></span><span><small>Neto</small><b>${moneyCLP(row.costNet)}</b></span><span><small>Vigente</small><b>${esc(row.effectiveDate)}</b></span><span><small>Margen ref.</small><b class="${row.margin!=null&&row.margin<0?"negative":""}">${row.margin==null?"Sin precio":row.margin.toFixed(1)+"%"}</b></span><button type="button" data-edit-cost="${esc(row.id)}">Editar</button></div>`).join(""):'<div class="crmCostEmpty">Todavía no hay costos cargados.</div>';rows.querySelectorAll("[data-edit-cost]").forEach(button=>button.onclick=()=>{const row=productCosts.find(x=>x.id===button.dataset.editCost);if(!row)return;const form=host.querySelector(".crmCostManual");form.elements.sku.value=row.sku;form.elements.product.value=row.product||"";form.elements.costGross.value=row.costGross;form.elements.effectiveDate.value=row.effectiveDate;form.elements.sku.focus();form.scrollIntoView({behavior:"smooth",block:"center"})})}
