function addCostManager(){const section=document.getElementById("v10security");if(!section||document.getElementById("crmCostManager"))return;const host=document.createElement("section");host.id="crmCostManager";host.className="crmCostManager";host.innerHTML=`<div class="crmCostHead"><div><small>COSTOS Y RENTABILIDAD</small><h2>Carga de costos por SKU</h2><p>Ingresa siempre el costo unitario <b>con IVA</b>. El CRM lo convierte a costo neto dividiendo por 1,19.</p></div><span class="crmVatBadge">IVA configurado: 19%</span></div><div class="crmCostKpis"></div><div class="crmCostMethods"><form class="crmCostExcel"><div><i class="fa-solid fa-file-excel"></i><span><b>1. Carga masiva por Excel</b><small>Columnas requeridas: SKU y Costo con IVA.</small></span></div><input class="crmCostFile" type="file" accept=".xlsx,.xls,.csv" hidden><div class="crmCostButtons"><button class="primary crmCostUpload" type="button">Seleccionar Excel</button><button class="soft crmCostTemplate" type="button">Descargar plantilla</button></div><p class="crmCostExcelStatus"></p></form><form class="crmCostManual"><div><i class="fa-solid fa-pen-to-square"></i><span><b>2. Edición manual</b><small>Crea o actualiza el costo vigente de un SKU.</small></span></div><div class="crmCostFields"><label>SKU<input name="sku" list="crmCostSkuList" placeholder="Ej. COSRX-001" required></label><label>Producto<input name="product" placeholder="Nombre opcional"></label><label>Costo unitario con IVA<input name="costGross" inputmode="decimal" placeholder="$ 0" required></label><label>Vigente desde<input name="effectiveDate" type="date" required></label></div><datalist id="crmCostSkuList"></datalist><button class="primary" type="submit">Guardar costo</button><p class="crmCostManualStatus"></p></form></div><div class="crmCostListHead"><div><b>Costos vigentes</b><small>Haz clic en Editar para cargar los datos en el formulario.</small></div><input class="crmCostSearch" type="search" placeholder="Buscar SKU o producto"></div><div class="crmCostRows"></div><p class="crmCostNote"><b>Fórmula:</b> costo neto = costo con IVA ÷ 1,19. El margen se calcula contra venta neta, también sin IVA. En esta prueba los costos quedan guardados en la base de este navegador.</p>`;section.appendChild(host);const file=host.querySelector(".crmCostFile"),excelStatus=host.querySelector(".crmCostExcelStatus"),manual=host.querySelector(".crmCostManual"),manualStatus=host.querySelector(".crmCostManualStatus"),canEdit=()=>{if(!window.CRMUsers||CRMUsers.can("supervise"))return true;alert("Solo un Administrador o Supervisor puede modificar costos.");return false};manual.elements.effectiveDate.value=new Date().toISOString().slice(0,10);crmDbAll("products").then(products=>{host.querySelector("#crmCostSkuList").innerHTML=products.sort((a,b)=>String(a.sku).localeCompare(String(b.sku))).map(row=>`<option value="${esc(row.sku)}">${esc(row.product||row.title||"")}</option>`).join("")});host.querySelector(".crmCostUpload").onclick=()=>{if(!canEdit())return;file.click()};host.querySelector(".crmCostTemplate").onclick=downloadCostTemplate;file.onchange=async()=>{const selected=file.files?.[0];if(!selected)return;excelStatus.textContent="Leyendo y validando costos…";try{const result=await importCostWorkbook(selected);excelStatus.textContent=`Listo: ${result.loaded} costos cargados${result.ignored?` · ${result.ignored} filas omitidas`:""}.`;await refreshCostUI()}catch(e){excelStatus.textContent=e.message}finally{file.value=""}};manual.onsubmit=async event=>{event.preventDefault();if(!canEdit())return;manualStatus.textContent="Guardando…";try{const data=Object.fromEntries(new FormData(manual));if(!data.product)data.product=productCostName(data.sku,await crmDbAll("products").catch(()=>[]));await saveProductCost(data);manualStatus.textContent=`Costo guardado. Neto calculado: ${moneyCLP(parseCostNumber(data.costGross)/(1+COST_TAX_RATE))}.`;manual.reset();manual.elements.effectiveDate.value=new Date().toISOString().slice(0,10);await refreshCostUI()}catch(e){manualStatus.textContent=e.message}};host.querySelector(".crmCostSearch").oninput=event=>drawCostManager(host,event.target.value);drawCostManager(host)}

function moneyCLP(v){return new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(+v||0)}
