function addPipelineViewport(){
  const host=document.getElementById("kanban");
  if(!host||host.dataset.viewportReady)return;
  host.dataset.viewportReady="1";
  const resizeColumns=()=>requestAnimationFrame(()=>{
    host.querySelectorAll(":scope > .col").forEach(col=>{
      const deals=[...col.querySelectorAll(":scope > .deal")];
      col.classList.toggle("pipelineScrollable",deals.length>20);
      col.removeAttribute("tabindex");
      col.removeAttribute("role");
      col.removeAttribute("aria-label");
      col.style.removeProperty("--pipeline-visible-height");
      if(deals.length<=20)return;
      const bottom=deals[19].offsetTop+deals[19].offsetHeight+9;
      col.style.setProperty("--pipeline-visible-height",Math.ceil(bottom)+"px");
      col.tabIndex=0;
      col.setAttribute("role","region");
      col.setAttribute("aria-label",`${col.querySelector("h3")?.textContent||"Etapa del pipeline"}. Se muestran 20 clientes a la vez; desplázate para ver los demás.`);
    });
  });
  new MutationObserver(resizeColumns).observe(host,{childList:true,subtree:true});
  window.addEventListener("resize",resizeColumns,{passive:true});
  resizeColumns();
}
